"""Existence and uniqueness of an incircle and the two families of axes in exercises 1174–1175."""
import argparse
import json
from math import cos,pi,sin
from coordinate_curves import graph
from triangle_sine_area import area
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/regular-polygon-centers.json'


def axes(title,n,j,at_vertices=False):
    angle=2*pi/n;r=4
    vertices=[(r*cos(i*angle),r*sin(i*angle)) for i in range(n)]
    names=['_poly'+str(i) for i in range(n)]
    for i,name in [(0,'A'),(1,'B'),(j,'C'),((j+1)%n,'D')]:
        if names[i].startswith('_'):names[i]=name
    pts=dict(zip(names,vertices));pts['T']=(0,0);edges=list(zip(names,names[1:]+names[:1]))
    for h,k in [('H',0),('K',j)]:
        x,y=vertices[k];z,w=vertices[(k+1)%n];pts[h]=((x+z)/2,(y+w)/2);edges.append(('T',h))
    lines=[]
    for i in (0,j):
        phi=i*angle+(0 if at_vertices else angle/2)
        # Opposite directions produce the very same line.
        if lines and abs(sin(phi-(0 if at_vertices else angle/2)))<1e-8:continue
        x,y=(r+1)*cos(phi),(r+1)*sin(phi)
        lines.append(((-x,-y),(x,y)))
    return graph(title,pts,edges=edges,circle=('T',r*cos(pi/n)),lines=lines)


def course(n,title,task,reason,hint,steps,views,checks,caption):
    theory=n==115
    e=area(n,None,[295,296,297] if theory else [300],task,reason,hint,steps,views,checks,title=title,refs=[113,114,115])
    e['source']['chapter']='XIII';e['review']['reviewer']='Атанасян 2023, п. 115 на печатных с. 295–297, исходные №1174–1175 на с. 300. Измерены обе окружности, точки касания и совпадение прямых в чётном случае.'
    model=e['visualization']['model']
    for v in model['views'].values():
        key={n:p for p in v['points'] for n in model['labels'][p].split('=')}
        v['circles'].append({'center':key['T'],'through':key['A']})
    e['visualization']['caption']=caption;model['description']=caption
    if not theory:
        e['help'][1]['text']=hint;e['answer']['prompt']='Докажи общий результат и опиши отдельно пример совпадения двух прямых.'
    return e


def theorem():
    views=[axes('Точки касания в правильном пятиугольнике',5,2),axes('Противоположные стороны правильного шестиугольника',6,3),axes('Вторая проверка на квадрате',4,1)]
    hint='Соедини центр описанной окружности с вершинами. У равных равнобедренных треугольников высоты к сторонам равны. Чтобы доказать единственность, найди пересечение внутренних биссектрис.'
    return course(115,'Окружность внутри правильного многоугольника','Почему в каждый правильный многоугольник можно вписать единственную окружность? Где лежат точки касания и как связаны центры двух окружностей?',
        'Пусть T — центр описанной окружности. Равные центральные треугольники имеют одинаковые высоты к сторонам многоугольника. Окружность с центром T и радиусом такой высоты касается всех сторон в основаниях перпендикуляров. Каждый центральный треугольник равнобедренный, поэтому его высота делит соответствующую сторону пополам. Любой возможный центр вписанной окружности равноудалён от соседних сторон и лежит на их внутренней биссектрисе. Две соседние биссектрисы определяют T, а расстояние от T до стороны однозначно даёт радиус.',hint,[
        ('Получи одну общую высоту','Треугольники с вершиной T, построенные на сторонах, равны по трём сторонам: два радиуса внешней окружности и сторона многоугольника. Поэтому TH и TK равны; такие же высоты получаются у остальных сторон.','Радиус к вершине и расстояние до стороны имеют разную длину.'),
        ('Найди точки касания','H и K — середины выбранных сторон: высота из вершины равнобедренного треугольника служит медианой. Круг радиуса TH находится внутри многоугольника и касается каждой стороны в середине. На втором чертеже обе точки лежат на общей прямой с T.','Центр лежит внутри выпуклого многоугольника.'),
        ('Докажи единственность','Другой центр тоже находился бы на внутренних биссектрисах всех вершин. Две соседние биссектрисы пересекаются в T, так что центр совпадает; радиус есть фиксированное расстояние до стороны. Для квадрата взаимное положение окружностей особенно хорошо видно.','Три касания на рисунке не заменяют доказательства для всех сторон.')],views,[
        ('Скольких сторон касается окружность внутри правильного шестиугольника?','6','У каждой из шести сторон по одной точке касания.'),('Сколько различных центров у вписанной и описанной окружностей квадрата?','1','Обе окружности имеют общий центр T.')],'Малая окружность касается сторон, большая проходит через вершины. H,K — середины двух выбранных сторон, T — общий центр.')


def perpendiculars():
    views=[axes('Две различные прямые в пятиугольнике',5,2),axes('Совпадение для противоположных сторон шестиугольника',6,3),axes('Соседние стороны квадрата',4,1)]
    hint='У концов каждой стороны одинаковое расстояние до T — радиус описанной окружности. Значит T принадлежит каждому серединному перпендикуляру, и две такие прямые имеют общую точку.'
    return course(1174,None,'Докажи, что серединные перпендикуляры к любым двум сторонам правильного многоугольника пересекаются или совпадают.',
        'Пусть сторона имеет концы A,B. Из TA=TB следует, что T лежит на серединном перпендикуляре к AB. Для второй стороны аргумент тот же. У двух различных прямых, содержащих T, единственная общая точка T; если направления одинаковы, это одна и та же прямая.',hint,[
        ('Найди точку на первой прямой','Любая вершина лежит на описанной окружности. У её центра T совпадают расстояния до A и B, значит T лежит на прямой через середину H стороны AB под прямым углом к AB.','Используй геометрическое место точек, равноудалённых от двух концов отрезка.'),
        ('Проверь случай совпадения','У противоположных сторон правильного шестиугольника середины H и K и центр T лежат на одной прямой. Эта прямая перпендикулярна обеим параллельным сторонам. Здесь получилась ровно одна геометрическая прямая.','Если перпендикуляры совпали, их общих точек бесконечно много.'),
        ('Поменяй выбор сторон','Для двух соседних сторон квадрата перпендикуляры имеют разные направления. Они встречаются в T под углом 90°. В общем случае наличие T уже исключает параллельные различные прямые.','Проверь направление обеих линий, а не только одинаковую длину TH и TK.')],views,[
        ('Сколько различных прямых получилось для противоположных сторон шестиугольника?','1','Обе линии имеют одинаковое направление и проходят через T.'),('Под каким углом, в градусах, пересекаются указанные линии для соседних сторон квадрата?','90','У каждой линии направление соответствующей стороны повёрнуто на 90°.')],'Выделены целиком две прямые через середины выбранных сторон. При совпадении видна одна линия. Стороны и точки касания показывают её положение.')


def bisectors():
    views=[axes('Оси двух углов в пятиугольнике',5,2,True),axes('Противоположные вершины правильного шестиугольника',6,3,True),axes('Соседние вершины квадрата',4,1,True)]
    hint='Центр вписанной окружности равноудалён от двух сторон каждого угла и находится внутри этого угла. Поэтому внутренняя биссектриса каждой вершины проходит через T.'
    return course(1175,None,'Докажи, что прямые, содержащие биссектрисы любых двух углов правильного многоугольника, либо пересекаются, либо совпадают.',
        'У любой вершины расстояния от T до обеих её сторон равны радиусу вписанной окружности. Так как T внутри угла, луч из вершины в T является внутренней биссектрисой. Обе полные прямые проходят через T, поэтому при разных направлениях пересекаются, а при одинаковом направлении совпадают.',hint,[
        ('Сравни расстояния от T до сторон угла','Оба перпендикулярных расстояния равны радиусу малой окружности. Прямоугольные треугольники с общей гипотенузой от вершины к T равны, так что луч к T делит угол пополам.','Без условия «внутри угла» равные расстояния могли бы указывать и на внешнюю биссектрису.'),
        ('Различи лучи и полные прямые','У противоположных вершин правильного шестиугольника биссектрисы направлены навстречу друг другу. Содержащие их полные прямые совпадают.','Исходное утверждение относится к прямым, содержащим биссектрисы.'),
        ('Рассмотри соседние вершины','У соседних вершин квадрата полные биссектрисы лежат на двух разных диагоналях. Они имеют только одну общую точку T и пересекаются под прямым углом.','Точка пересечения общая для любой пары; совпадение зависит от выбора вершин.')],views,[
        ('Сколько разных прямых содержат биссектрисы выбранных противоположных углов шестиугольника?','1','Обе проходят через противоположные вершины и T.'),('Сколько общих точек у двух таких различных прямых для соседних вершин квадрата?','1','Их единственная общая точка — T.')],'Выделены линии, проходящие через вершины и T. Точки H,K отмечены на сторонах и не задают направление биссектрис при вершинах.')


def build():
    return {'bookId':BOOK,'lessons':[theorem(),perpendiculars(),bisectors()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true')
    text=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==text
    else:OUT.write_text(text)
